import { test, expect } from '@playwright/test';

test('shows the newest order', async ({ page }) => {
  await page.goto('/login');
  await page.locator('form input:nth-child(1)').fill('user@example.com');
  await page.locator('form input:nth-child(2)').fill('password123');
  await page.locator('.btn-primary').click();
  await page.waitForTimeout(3000);

  await expect(
    page.locator('table tr:nth-child(1) td:nth-child(3)')
  ).toHaveText('2024-01-15 14:30:00');
});

test('filters orders by status', async ({ page }) => {
  await page.goto('/login');
  await page.locator('form input:nth-child(1)').fill('user@example.com');
  await page.locator('form input:nth-child(2)').fill('password123');
  await page.locator('.btn-primary').click();
  await page.waitForTimeout(3000);

  await page.locator('select#status-filter').selectOption('shipped');
  await page.waitForTimeout(3000);

  await expect(
    page.locator('table tr:nth-child(1) td:nth-child(2)')
  ).toHaveText('Shipped');
});

test('opens an order detail', async ({ page }) => {
  await page.goto('/login');
  await page.locator('form input:nth-child(1)').fill('user@example.com');
  await page.locator('form input:nth-child(2)').fill('password123');
  await page.locator('.btn-primary').click();
  await page.waitForTimeout(3000);

  await page.locator('table tr:nth-child(1) td:nth-child(1)').click();

  await expect(page.locator('h1')).toHaveText('Order Detail');
});
